// ====================== REQUESTS ======================data class LoginRequest(    val email: String,    val password: String)data class RegisterRequest(    val email: String,    val password: String,    val firstName: String,    val lastName: String)data class RefreshTokenRequest(    val refreshToken: String?,    val useCookies: Boolean = false)data class VerifyEmailRequest(    val email: String,    val otp: String)data class ChangePasswordRequest(    val currentPassword: String,    val newPassword: String,    val confirmNewPassword: String)data class ForgotPasswordRequest(    val email: String)data class ResendOtpRequest(    val email: String)data class ValidateOtpRequest(    val email: String,    val otp: String)data class ResetPasswordRequest(    val email: String,    val otp: String,    val newPassword: String)data class GoogleMobileSignInRequest(    val idToken: String)